            const isY = grid[r][c] === 'Y' ? 1 : 0;
            px[r + 1][c + 1] = px[r][c + 1] + px[r + 1][c] - px[r][c] + isX;
            py[r + 1][c + 1] = py[r][c + 1] + py[r + 1][c] - py[r][c] + isY;
